script:
frappe.ui.form.on('Sales Invoice', {
	refresh(frm) {
		// your code here
	},
	customer(frm){
	    frm.trigger('set_gstin_taxes');
	},
	dispatch_address_name(frm){
	    frm.trigger('set_gstin_taxes');
	},
	shipping_address_name(frm){
	    frm.trigger('set_gstin_taxes');
	},
	validate(frm){
	    frm.trigger('set_gstin_taxes');  
	},
	set_gstin_taxes(frm){
	    if (!frm.doc.customer && !frm.doc.dispatch_address_name && !frm.doc.shipping_address_name){
	        return;
	    }

	    frappe.call({
	        'method': 'frappe.client.get_list',
	        'args': {
	            'doctype': 'Address',
	            'fields': ['name', 'state_rigpl', 'country'],
	            'filters': {
	                'name': ['in', [frm.doc.dispatch_address_name, frm.doc.shipping_address_name]]
	            }
	        },
	        callback(res){
	            let by_id = {}, 
	                shipping = frm.doc.shipping_address_name,
	                dispatch = frm.doc.dispatch_address_name;

	            res.message.forEach(address => by_id[address.name] = address);

	            if (by_id[shipping].country == by_id[dispatch].country) {
	                if (by_id[shipping].state_rigpl == by_id[dispatch].state_rigpl){
	                    frm.set_value('taxes_and_charges', 'RIGB GST Local Sales');
	                } else {
	                    frm.set_value('taxes_and_charges', 'RIGB GST Central Sales');
	                }
	            } else {
	                frm.set_value('taxes_and_charges', 'RIGB Export Under Bond');
	            }

	        }
	    });


	}
});
